import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate, useParams } from "react-router-dom";
import private_api from "../../server/private_api";
import Modal from 'react-bootstrap/Modal';
import Button from 'react-bootstrap/Button';
import Form from 'react-bootstrap/Form';
import Alert from 'react-bootstrap/Alert';

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [alunos, setAlunos] = useState([]);
  const [selectedCurso, setSelectedCurso] = useState(null);
  const [loading, setLoading] = useState(true);
  const [loadingAlunos, setLoadingAlunos] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [selectedAlunos, setSelectedAlunos] = useState([]);
  const [mensagem, setMensagem] = useState("");
  const [assunto, setAssunto] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [enviado, setEnviado] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const { id } = useParams();

  // ... (mantenha as funções fetchCursos e fetchAlunosDoCurso existentes)

  const handleAlunoSelection = (alunoId) => {
    setSelectedAlunos(prev => {
      if (prev.includes(alunoId)) {
        return prev.filter(id => id !== alunoId);
      } else {
        return [...prev, alunoId];
      }
    });
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedAlunos(alunos.map(aluno => aluno.id));
    } else {
      setSelectedAlunos([]);
    }
  };

  const handleEnviarAvisos = async () => {
    if (!assunto || !mensagem || selectedAlunos.length === 0) {
      setError("Preencha todos os campos e selecione pelo menos um aluno");
      return;
    }
    
    setEnviando(true);
    setError(null);
    
    try {
      // Para cada aluno selecionado, enviar um email
      const promises = selectedAlunos.map(alunoId => {
        const aluno = alunos.find(a => a.id === alunoId);
        return private_api.post('/notificacao', {
          to: aluno.utilizador.email,
          subject: assunto,
          text: mensagem
        });
      });
      
      await Promise.all(promises);
      
      setEnviado(true);
      setTimeout(() => {
        setShowModal(false);
        setEnviado(false);
        setSelectedAlunos([]);
        setMensagem("");
        setAssunto("");
      }, 2000);
    } catch (error) {
      console.error("Erro ao enviar avisos:", error);
      setError("Erro ao enviar avisos. Por favor, tente novamente.");
    } finally {
      setEnviando(false);
    }
  };

  // ... (mantenha o restante do código existente até a tabela de alunos)

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      {/* ... (mantenha o nav e tabela de cursos existentes) */}

      {/* Lista de Alunos do Curso Selecionado */}
      {selectedCurso && (
        <div className="w-75">
          <div className="d-flex justify-content-between align-items-center mb-3">
            <h3 className="mb-0">
              Alunos do Curso: {selectedCurso.nome}
            </h3>
            {alunos.length > 0 && (
              <Button 
                variant="primary" 
                onClick={() => setShowModal(true)}
                disabled={selectedAlunos.length === 0}
              >
                Emitir Avisos
              </Button>
            )}
          </div>
          
          {loadingAlunos ? (
            <div className="d-flex justify-content-center mt-3">
              Carregando alunos...
            </div>
          ) : (
            <table className="table table-bordered bg-white">
              <thead>
                <tr>
                  <th>
                    <Form.Check
                      type="checkbox"
                      onChange={handleSelectAll}
                      checked={selectedAlunos.length === alunos.length && alunos.length > 0}
                    />
                  </th>
                  <th>Nome</th>
                  <th>Email</th>
                </tr>
              </thead>
              <tbody>
                {alunos.length > 0 ? (
                  alunos.map((aluno) => (
                    <tr key={aluno.id}>
                      <td>
                        <Form.Check
                          type="checkbox"
                          checked={selectedAlunos.includes(aluno.id)}
                          onChange={() => handleAlunoSelection(aluno.id)}
                        />
                      </td>
                      <td>{aluno.utilizador?.nome}</td>
                      <td>{aluno.utilizador?.email}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="4" className="text-center">
                      Nenhum aluno matriculado neste curso
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* Modal para enviar avisos */}
      <Modal show={showModal} onHide={() => !enviando && setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Enviar Aviso aos Alunos</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {enviado ? (
            <Alert variant="success" className="text-center">
              <Alert.Heading>Avisos enviados com sucesso!</Alert.Heading>
              <p>Os avisos foram enviados para os emails dos alunos selecionados.</p>
            </Alert>
          ) : (
            <>
              {error && <Alert variant="danger">{error}</Alert>}
              
              <Form.Group className="mb-3">
                <Form.Label>Assunto:</Form.Label>
                <Form.Control
                  type="text"
                  value={assunto}
                  onChange={(e) => setAssunto(e.target.value)}
                  placeholder="Digite o assunto do aviso"
                  disabled={enviando}
                />
              </Form.Group>
              
              <Form.Group className="mb-3">
                <Form.Label>Mensagem:</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={5}
                  value={mensagem}
                  onChange={(e) => setMensagem(e.target.value)}
                  placeholder="Digite a mensagem que será enviada por email"
                  disabled={enviando}
                />
              </Form.Group>
              
              <div className="mb-3">
                <h5>Alunos selecionados ({selectedAlunos.length}):</h5>
                <div style={{ maxHeight: '200px', overflowY: 'auto' }}>
                  <ul className="list-group">
                    {alunos
                      .filter(aluno => selectedAlunos.includes(aluno.id))
                      .map(aluno => (
                        <li key={aluno.id} className="list-group-item">
                          {aluno.utilizador?.nome} - {aluno.utilizador?.email}
                        </li>
                      ))}
                  </ul>
                </div>
              </div>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          {!enviado && (
            <>
              <Button 
                variant="secondary" 
                onClick={() => setShowModal(false)}
                disabled={enviando}
              >
                Cancelar
              </Button>
              <Button 
                variant="primary" 
                onClick={handleEnviarAvisos}
                disabled={enviando || !assunto || !mensagem}
              >
                {enviando ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Enviando...
                  </>
                ) : 'Enviar Avisos'}
              </Button>
            </>
          )}
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default LecionaLista;
